const envUrl = process.env.SCALEKIT_ENV_URL;
const clientId = process.env.SCALEKIT_CLIENT_ID;
const clientSecret = process.env.SCALEKIT_CLIENT_SECRET;

if (!envUrl || !clientId || !clientSecret) {
  console.error('Missing Scalekit environment variables');
  process.exit(1);
}

const scalekit = new ScalekitClient(envUrl, clientId, clientSecret);

async function main() {
  const runId = process.env.ZEALT_RUN_ID;
  const channelName = `agentkit-demo-${runId}`;
  console.log(`Waiting and listing for channel: ${channelName}`);
  for (let i = 0; i < 10; i++) {
    try {
      const listResult = await scalekit.actions.executeTool({
        toolName: 'slack_list_channels',
        toolInput: {
          types: 'public_channel,private_channel'
        },
        identifier: 'zealt-user01',
        connector: 'slack-test'
      });
      const channels = (listResult.data as any)?.channels || [];
      const found = channels.find((c: any) => c.name === channelName);
      if (found) {
        console.log(`Found channel! ID: ${found.id}`);
        break;
      } else {
        console.log(`[${i}] Channel not found yet. Total channels listed: ${channels.length}`);
      }
    } catch (e) {
      console.error('Error listing:', e);
    }
    await new Promise((resolve) => setTimeout(resolve, 2000));
  }
}

main();

